css:
.install-btn {
  position: relative;
  width: 76px;
  height: 76px;
  padding: 0;
  background: #18181b;
  border: none;
  border-radius: 50%;
  cursor: pointer;
  outline: none;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow:
    0 8px 24px -4px rgba(0, 0, 0, 0.5),
    0 0 0 1px rgba(255, 255, 255, 0.08);
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
  -webkit-tap-highlight-color: transparent;
}

.install-btn:hover {
  transform: translateY(-2px);
  box-shadow:
    0 12px 28px -4px rgba(0, 0, 0, 0.6),
    0 0 16px rgba(56, 189, 248, 0.2);
}

.install-btn:active {
  transform: translateY(1px);
}

.install-btn__svg {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  transform: rotate(-90deg);
}

.install-btn__mask-circle {
  fill: none;
  stroke: #ffffff;
  stroke-width: 5px;
}

.install-btn__track {
  fill: none;
  stroke: rgba(255, 255, 255, 0.12);
  stroke-width: 5px;
}

.install-btn__fill {
  fill: none;
  stroke: #38bdf8;
  stroke-width: 5px;
  stroke-dasharray: 264;
  stroke-dashoffset: 264;
}

.install-btn__icon {
  width: 24px;
  height: 24px;
  color: #f4f4f5;
  z-index: 1;
  transition:
    transform 0.2s ease,
    color 0.2s ease;
}

/* Запуск при нажатии (клике) */
.install-btn:focus .install-btn__fill {
  animation: install-btn-random-progress 4.2s cubic-bezier(0.25, 0.1, 0.25, 1)
    forwards;
}

.install-btn:focus .install-btn__icon {
  color: #38bdf8;
  animation: install-btn-bounce 0.6s ease;
}

/* 
  Неравномерное заполнение 5 секторов с паузами и рывками 
  (полная длина = 264px, шаг секции = 52.8px)
*/
@keyframes install-btn-random-progress {
  0% {
    stroke-dashoffset: 264;
  }
  /* 1-я секция: быстрый старт и короткая пауза */
  14% {
    stroke-dashoffset: 211.2;
  }
  22% {
    stroke-dashoffset: 211.2;
  }
  /* 2-я секция: длительное, медленное скачивание */
  48% {
    stroke-dashoffset: 158.4;
  }
  /* 3-я секция: резкий скачок и зависание */
  56% {
    stroke-dashoffset: 105.6;
  }
  68% {
    stroke-dashoffset: 105.6;
  }
  /* 4-я секция: размеренное заполнение */
  84% {
    stroke-dashoffset: 52.8;
  }
  /* 5-я секция: финальный рывок до 100% */
  93%,
  100% {
    stroke-dashoffset: 0;
  }
}

@keyframes install-btn-bounce {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(3px);
  }
}
